using System;using System.IO;using SolidWorks.Interop.sldworks;using SolidWorks.Interop.swconst;
public class VerifyV3 {
 public static void Run(string root){var sw=(SldWorks)Activator.CreateInstance(Type.GetTypeFromProgID("SldWorks.Application.32"));string dir=Path.Combine(root,"OPIZ3_v3");using(var log=new StreamWriter(Path.Combine(dir,"verification.txt"))){log.AutoFlush=true;
 foreach(string p in Directory.GetFiles(dir,"*.SLDPRT")){if(Path.GetFileName(p).StartsWith("~$"))continue;int e=0,w=0;var m=(ModelDoc2)sw.OpenDoc6(p,1,1,"",ref e,ref w);if(m==null)throw new Exception("Open failed "+p);int a=0;sw.ActivateDoc3(m.GetTitle(),false,0,ref a);m.SetUserPreferenceToggle((int)swUserPreferenceToggle_e.swDisplayOrigins,false);m.SetUserPreferenceToggle((int)swUserPreferenceToggle_e.swDisplayPlanes,false);m.ForceRebuild3(false);log.WriteLine(Path.GetFileName(p)+" open="+e+" warnings="+w);var f=(Feature)m.FirstFeature();int errors=0;while(f!=null){bool warning=false;int code=f.GetErrorCode2(out warning);if(code!=0){log.WriteLine("  "+f.Name+" code="+code+" warning="+warning);if(!warning)errors++;}f=(Feature)f.GetNextFeature();}log.WriteLine("  feature errors="+errors);if(Path.GetFileName(p).Equals("REF_TFT_exact.SLDPRT")){log.WriteLine("  imported reference preserved unchanged");}else{m.Save3(1,ref e,ref w);log.WriteLine("  save="+e+" warnings="+w);}}
 int ee=0,ww=0;var am=(ModelDoc2)sw.OpenDoc6(Path.Combine(dir,"OPIZ3_assembly.SLDASM"),2,1,"",ref ee,ref ww);int ae=0;sw.ActivateDoc3(am.GetTitle(),false,0,ref ae);var ass=(AssemblyDoc)am;ass.ResolveAllLightWeightComponents(false);am.ForceRebuild3(false);
 object[] cs=(object[])ass.GetComponents(false);log.WriteLine("Assembly components="+cs.Length);foreach(Component2 c in cs){double[] color=c.Name2.StartsWith("REF_TFT")?new double[]{0.08,0.45,0.65,0.5,0.7,0.3,0.4,0,0}:(c.Name2.StartsWith("08_")?new double[]{0.95,0.35,0.07,0.5,0.7,0.3,0.3,0,0}:new double[]{0.27,0.31,0.35,0.5,0.7,0.3,0.3,0,0});if(c.Name2.StartsWith("REF_TFT_exact"))c.RemoveMaterialProperty();else c.MaterialPropertyValues=color;log.WriteLine(c.Name2+" transform="+String.Join(",",(double[])c.Transform2.ArrayData));}
 CheckAxes(sw,cs,log);var mgr=(InterferenceDetectionMgr)ass.InterferenceDetectionManager;mgr.TreatCoincidenceAsInterference=false;mgr.IncludeMultibodyPartInterferences=true;mgr.IgnoreHiddenBodies=false;object[] hits=(object[])mgr.GetInterferences();log.WriteLine("Interference count="+(hits==null?0:hits.Length));if(hits!=null)foreach(Interference h in hits){log.Write("INTERFERENCE volume_mm3="+(h.Volume*1e9)+" components=");foreach(Component2 c in (object[])h.Components)log.Write(c.Name2+" ");var ib=(Body2)h.GetInterferenceBody();log.WriteLine("bbox="+String.Join(",",(double[])ib.GetBodyBox()));}mgr.Done();
 am.ClearSelection2(true);am.SetUserPreferenceToggle((int)swUserPreferenceToggle_e.swDisplayPlanes,false);am.SetUserPreferenceToggle((int)swUserPreferenceToggle_e.swDisplayOrigins,false);am.ShowNamedView2("*Isometric",7);var mv=(ModelView)am.ActiveView;mv.DisplayMode=4;
 // Orient physical Z vertically using a camera with a forward/left vantage point.
 var math=(MathUtility)sw.GetMathUtility();double inv=Math.Sqrt(0.5),s=Math.Sqrt(1.0/6),cc=Math.Sqrt(2.0/3);
 mv.Orientation3=(MathTransform)math.CreateTransform(new double[]{inv,-s,s*Math.Sqrt(2),inv,s,-s*Math.Sqrt(2),0,cc,1/Math.Sqrt(3),0,0,0,1,0,0,0});
 am.ViewZoomtofit2();am.Save3(1,ref ee,ref ww);am.Extension.SaveAs(Path.Combine(dir,"assembly_preview.png"),0,1,null,ref ee,ref ww);log.WriteLine("Preview="+ee);Console.WriteLine("Verification written");}}
 static double[] World(MathUtility math,double[] p,MathTransform tr){return (double[])((MathPoint)((MathPoint)math.CreatePoint(new double[]{p[0],p[1],p[2]})).MultiplyTransform(tr)).ArrayData;}
 static double DistanceAxis(MathUtility math,double[] point,MathTransform pt,double[] hole,MathTransform ht){var pp=World(math,point,pt);var hp=World(math,hole,ht);var end=World(math,new double[]{hole[0]+hole[3],hole[1]+hole[4],hole[2]+hole[5]},ht);double dot=0,nn=0,dd=0;for(int i=0;i<3;i++){double n=end[i]-hp[i],d=pp[i]-hp[i];dot+=n*d;nn+=n*n;dd+=d*d;}return Math.Sqrt(Math.Max(0,dd-dot*dot/nn));}
 static double[][] Cylinders(Component2 c,double radius){var ls=new System.Collections.Generic.List<double[]>();var part=(PartDoc)c.GetModelDoc2();foreach(Body2 b in (object[])part.GetBodies2(0,false))foreach(Face2 f in (object[])b.GetFaces()){var s=(Surface)f.GetSurface();if(s.IsCylinder()){var p=(double[])s.CylinderParams;if(Math.Abs(p[6]-radius)<1e-8)ls.Add(p);}}return ls.ToArray();}
 static void CheckAxes(SldWorks sw,object[] cs,StreamWriter log){Component2 pcb=null,panel=null,cage=null;foreach(Component2 c in cs){if(c.Name2.StartsWith("REF_TFT_exact"))pcb=c;if(c.Name2.StartsWith("05_display_panel"))panel=c;if(c.Name2.StartsWith("03_disk_cage"))cage=c;}var math=(MathUtility)sw.GetMathUtility();int count=0;double worst=0;foreach(var p in Cylinders(pcb,0.0016)){double best=double.PositiveInfinity;foreach(var h in Cylinders(panel,0.0013))best=Math.Min(best,DistanceAxis(math,p,pcb.Transform2,h,panel.Transform2));count++;worst=Math.Max(worst,best);}log.WriteLine("TFT actual STEP hole axes="+count+" max_offset_mm="+worst*1000);if(count!=4||worst>1e-6)throw new Exception("PCB holes do not align");worst=0;count=0;foreach(var p in Cylinders(panel,0.0017)){if(Math.Abs(p[3])<0.99)continue;double best=double.PositiveInfinity;foreach(var h in Cylinders(cage,0.0017))if(Math.Abs(h[3])>0.99)best=Math.Min(best,DistanceAxis(math,p,panel.Transform2,h,cage.Transform2));count++;worst=Math.Max(worst,best);}log.WriteLine("Tilt lock hole axes="+count+" max_offset_mm="+worst*1000);if(count<4||worst>1e-6)throw new Exception("Tilt lock holes do not align");}}







